import{_ as t,a}from"./chunks/reportverwaltung.BMspAEu6.js";import{_ as s,o as l,c as o,a3 as n,j as e,a as i}from"./chunks/framework.z_KJ15Ep.js";const w=JSON.parse('{"title":"Den Reportdesigner öffnen und verwenden","description":"","frontmatter":{"title":"Den Reportdesigner öffnen und verwenden","source_pageid":1526,"source_revision":7142},"headers":[],"relativePath":"reporting/reportdesigner/reportdesigner.md","filePath":"reporting/reportdesigner/reportdesigner.md"}'),u={name:"reporting/reportdesigner/reportdesigner.md"};function d(g,r,p,h,f,m){return l(),o("div",null,[...r[0]||(r[0]=[n('<h1 id="den-reportdesigner-offnen-und-verwenden" tabindex="-1">Den Reportdesigner öffnen und verwenden <a class="header-anchor" href="#den-reportdesigner-offnen-und-verwenden" aria-label="Permalink to &quot;Den Reportdesigner öffnen und verwenden&quot;">​</a></h1><p>Mit dem Reportdesigner gestalten Sie Reportvorlagen für Ausdrucke, PDF-Dateien und E-Mails. Hier finden Sie den Aufruf, den Speicherort der Vorlagen und die weiterführenden Anleitungen.</p><h2 id="aufruf-und-funktionsweise-des-reportdesigners" tabindex="-1">Aufruf und Funktionsweise des Reportdesigners <a class="header-anchor" href="#aufruf-und-funktionsweise-des-reportdesigners" aria-label="Permalink to &quot;Aufruf und Funktionsweise des Reportdesigners&quot;">​</a></h2><p><a href="/bilder/reportdesigner/reportdesigner.png"><img src="'+t+'" alt="Der Reportdesigner" loading="lazy"></a></p><p><em>Der Reportdesigner</em></p><p>Mit dem <strong>Reportdesigner</strong> erstellen oder ändern Sie Reportvorlagen. Eine Vorlage legt fest, welche Daten ausgegeben werden und wie das Dokument aussieht. Die Ausgabe können Sie drucken, als PDF speichern oder per E-Mail versenden. Der Reportdesigner stammt von <a href="https://www.digital-metaphors.com" target="_blank" rel="noreferrer">Digital Metaphors</a> und ist in SchILD-NRW 3 eingebunden.</p><p><a href="/bilder/reportdesigner/reportverwaltung.png"><img src="'+a+'" alt="Die Reportverwaltung" loading="lazy"></a></p><p><em>Die Reportverwaltung</em></p><p>Eine Reportvorlage wird als Datei mit der Endung <code>.rtm</code> unter <code>SVWS-Arbeitsverzeichnis\\Schild-Reports\\</code> gespeichert. Die <strong>Reportverwaltung</strong> zeigt die dort verfügbaren Vorlagen an.</p><ul><li><strong>Vorhandene Vorlage bearbeiten:</strong> Klicken Sie mit der rechten Maustaste auf die RTM-Datei und wählen Sie <strong>Report bearbeiten</strong>.</li><li><strong>Neue Vorlage erstellen:</strong> Klicken Sie in der Reportverwaltung auf <strong>Neu</strong>.</li></ul><p>RTM-Dateien können im Reportordner ergänzt oder gelöscht werden.</p><h2 id="die-basisreportsammlungen" tabindex="-1">Die Basisreportsammlungen <a class="header-anchor" href="#die-basisreportsammlungen" aria-label="Permalink to &quot;Die Basisreportsammlungen&quot;">​</a></h2><p>Mit der Installation von SchILD-NRW 3 wird eine Basisreportsammlung einmalig im SVWS-Arbeitsverzeichnis hinterlegt. Diese enthält Reports für typische Bedarfe in Schule. Diese Reports folgen einer konsequenten Designrichtlinie, haben einen gleichen Aufbau und sind ein guter Ausgangspunkt, eigene Varianten eines Reports zu bauen.</p>',13),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),i("Hinweis – Download")]),e("p",null,[e("a",{href:"https://github.com/SVWS-NRW/Schild-NRW-3-Reports/releases",target:"_blank",rel:"noreferrer"},"Laden Sie über diesen Link die neuste Version der Basisreportsammlung auf GitHub herunter."),i(" Schauen Sie regelmäßig vorbei. Vielleicht benötigen Sie keinen eigenen Report.")])],-1),n('<p>Die Basisreportsammlung wird bei der Erst-Installation von SchILD-NRW 3 im SVWS-Arbeitsverzeichnis hinterlegt. Diese wird jedoch bei Updates nicht weiter aktualisiert. Sie wächst im Release-Bereich auf GitHub jedoch stetig und behutsam weiter. Sie können dort jederzeit die neuste Sammlung herunterladen, um Ihre Reports in SchILD-NRW 3 zu ergänzen und auf den neusten Stand zu bringen.</p><ul><li><a href="/reporting/basisreports/basisreportsammlung-herunterladen-und-aktualisieren.html">Die Basisreportsammlung herunterladen und aktualisieren</a></li><li><a href="/reporting/basisreports/basisreportsammlung-ein-ueberblick.html">Die Basisreportsammlung im Überblick</a></li><li><a href="/reporting/basisreports/basisreportsammlung-designrichtlinien.html">Reports übersichtlich und wartbar gestalten</a></li><li><a href="/reporting/serienbriefe/basisreportsammlung-serienbriefe.html">Serienbriefe einrichten und drucken</a></li><li><a href="/reporting/serienbriefe/basisreportsammlung-einen-serienbrieftext-erstellen-schritt-fuer-schritt.html">Serienbrieftexte erstellen und wiederverwenden</a></li><li><a href="/reporting/serienbriefe/platzhalter.html">Platzhalter für Serienbriefe</a></li><li><a href="/reporting/serienbriefe/basisreportsammlung-serienbrief-mahnung-gefaehrdete-versetzung.html">Serienbrief zur Mahnung bei gefährdeter Versetzung</a></li><li><a href="/reporting/serienbriefe/basisreportsammlung-serienbrief-nichtversetzung.html">Serienbriefe zur Nichtversetzung erstellen</a></li><li><a href="/reporting/basisreports/basisreportsammlung-leistungsuebersichten-halbjahr.html">Leistungsübersichten für ein Halbjahr</a></li><li><a href="/reporting/basisreports/basisreportsammlung-leistungsuebersichten-jg-q1-bis-q2.html">Leistungsübersichten für Q1 und Q2</a></li><li><a href="/reporting/serienbriefe/basisreportsammlung-bescheinigungen-des-bilingualen-bildungsgangs.html">Bescheinigungen für den bilingualen Bildungsgang erstellen</a></li><li><a href="/reporting/basisreports/basisreportsammlung-aufnahmeboegen.html">Aufnahmebögen verwenden und anpassen</a></li><li><a href="/reporting/archiv/basisreportsammlung-versionsgeschichte.html">Versionsgeschichte der Basisreportsammlung</a></li></ul><h2 id="einfuhrung-in-den-reportdesigner" tabindex="-1">Einführung in den Reportdesigner <a class="header-anchor" href="#einfuhrung-in-den-reportdesigner" aria-label="Permalink to &quot;Einführung in den Reportdesigner&quot;">​</a></h2><ul><li><a href="/reporting/reportdesigner/was-leistet-ein-report-in-schild-nrw-3.html">Wie ein Report Daten zu einer Ausgabe zusammenführt</a></li><li><a href="/reporting/reportdesigner/neuen-report-erstellen.html">Einen Report ohne Assistenten erstellen</a></li><li><a href="/reporting/reportdesigner/einen-vorhandenen-report-anpassen.html">Einen vorhandenen Report anpassen</a></li><li><a href="/reporting/reportdesigner/einen-neuen-report-mit-dem-berichtsassistenten-erstellen.html">Einen Report mit dem Berichtsassistenten erstellen</a>´</li><li><a href="/reporting/programmierung/einen-subreport-dynamisch-in-einen-report-einbinden.html">Einen Subreport dynamisch einbinden</a></li><li><a href="/reporting/programmierung/programmierung-in-reports.html">Reports mit Object Pascal erweitern</a></li><li><a href="/reporting/programmierung/eigene-datenquellen.html">Eigene Datenquellen für Reports definieren</a></li><li><a href="/reporting/rap.html" title="RAP-Funktionen">RAP-Funktionen im Reportdesigner</a></li><li><a href="/reporting/reportdesigner/glossar-zum-reportdesigner.html">Begriffe des Reportdesigners</a></li><li><a href="/reporting/basisreports/basisreportsammlung-designrichtlinien.html">Reports übersichtlich und wartbar gestalten</a></li></ul><h2 id="vertiefende-pdf-tutorials-und-support" tabindex="-1">Vertiefende PDF-Tutorials und Support <a class="header-anchor" href="#vertiefende-pdf-tutorials-und-support" aria-label="Permalink to &quot;Vertiefende PDF-Tutorials und Support&quot;">​</a></h2><p>Neben den schulspezifischen Anleitungen und Hilfen in dieser Dokumentation können Sie Hilfe zur Erstellung eigener Reports im Anwenderforum finden. Laden Sie hierzu Ihren Report im Forum hoch und äußern Sie Ihre Anforderungen.</p><ul><li><a href="https://schulverwaltungsinfos.nrw.de/svws/forum/" target="_blank" rel="noreferrer">Link zum SchILD-NRW 3 Anwenderforum</a></li></ul><p>Jede Bezirksregierung bietet kostenlose Fortbildungsmodule rund um SchILD-NRW für Angestellte des Landes-NRW an. Unter den Angeboten finden Sie auch Fortbildungen zum Reportdesigner. Nehmen Sie gerne an diesen Fortbildungsangeboten teil.</p><ul><li><a href="https://www.svws.nrw.de/service/fortbildungen" target="_blank" rel="noreferrer">Fortbildungen der Bezirksregierungen</a></li></ul><p>Auf der Internetseite des Herstellers finden Sie gute deutschsprachige Anleitungen als PDF-Dokumente, welche Sie in die Bedienung des Reportdesigners einführen und Schritt für Schritt dem Ziel der Erstellung eines eigenen Reports näherbringen. Hierzu finden Sie neben einer grundlegenden Anleitung auch eine vertiefende Anleitung, welche Sie in die Programmieroberfläche des Reportdesigners einführt.</p><ul><li><a href="https://www.digital-metaphors.com/download/documentation/#LearningReportBuilder" target="_blank" rel="noreferrer">Link zu den deutschsprachigen Tutorials von Digital-Metaphors</a></li><li><a href="https://www.digital-metaphors.com/support/" target="_blank" rel="noreferrer">Link zur Support-Seite von Digital-Metaphors</a></li></ul><h2 id="weitere-tipps-zur-reportverwaltung" tabindex="-1">Weitere Tipps zur Reportverwaltung <a class="header-anchor" href="#weitere-tipps-zur-reportverwaltung" aria-label="Permalink to &quot;Weitere Tipps zur Reportverwaltung&quot;">​</a></h2><ul><li><a href="/reporting/reportverwaltung/die-ordnerstruktur-der-reportverwaltung.html" title="Die Ordnerstruktur der Reportverwaltung">Die Ordnerstruktur der Reportverwaltung</a></li><li><a href="/reporting/reportverwaltung/reports-in-die-reportverwaltung-einfuegen.html" title="Reports in die Reportverwaltung einfügen">Reports in die Reportverwaltung einfügen</a></li><li><a href="/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html">Zeugnisformulare herunterladen und bereitstellen</a></li><li><a href="/reporting/reportverwaltung/reports-ueber-den-schnellzugriff-aufrufen.html" title="Reports über den Schnellzugriff aufrufen">Reports über den Schnellzugriff aufrufen</a></li><li><a href="/reporting/serienbriefe/direkter-zugriff-auf-das-schuelerstammblatt-und-die-schulbescheinigung.html">Stammblatt und Schulbescheinigung direkt aufrufen</a></li><li><a href="/reporting/reportverwaltung/daten-aus-zurueckliegenden-abschnitten-drucken.html" title="Daten aus zurückliegenden Abschnitten drucken">Daten aus zurückliegenden Abschnitten drucken</a></li><li><a href="/reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.html">Reportausgaben und Zeugnisse archivieren</a></li><li><a href="/reporting/reportdesigner/serien-e-mail-versand.html">Reportausgaben als Serien-E-Mail versenden</a></li><li><a href="/reporting/reportdesigner/verzeichnis-der-dokumentenverwaltung-aendern-tutorial.html">Das Verzeichnis der Dokumentenablage ändern</a></li><li><a href="/reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.html" title="Einen Report per E-Mail versenden und teilen">Einen Report per E-Mail versenden und teilen</a></li><li><a href="/reporting/archiv/kompatibilitaet-der-reports-in-schild-nrw-2-und-schild-nrw-3.html">Reports zwischen SchILD-NRW 2 und 3 umstellen</a></li></ul><h2 id="problemlosungen" tabindex="-1">Problemlösungen <a class="header-anchor" href="#problemlosungen" aria-label="Permalink to &quot;Problemlösungen&quot;">​</a></h2><ul><li><a href="/reporting/reportdesigner/problem-bei-der-verwendung-von-grafiken-tutorial.html">Grafikfehler in Reports beheben</a></li><li><a href="/reporting/reportdesigner/probleme-mit-fehlenden-schriftarten-im-pdf-dokument-tutorial.html">Schriftarten und Sonderzeichen in PDF-Ausgaben</a></li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Reportdesigner" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7142.</p>',17)])])}const v=s(u,[["render",d]]);export{w as __pageData,v as default};
